import datetime
import unittest

from daterange import parse_range

D = datetime.date


class TestDates(unittest.TestCase):
    def test_two_dates(self):
        self.assertEqual(parse_range("2026-10-01..2026-10-31"), (D(2026, 10, 1), D(2026, 10, 31)))

    def test_same_day(self):
        self.assertEqual(parse_range("2026-10-05..2026-10-05"), (D(2026, 10, 5), D(2026, 10, 5)))

    def test_across_years(self):
        self.assertEqual(parse_range("2025-12-30..2026-01-02"), (D(2025, 12, 30), D(2026, 1, 2)))

    def test_reversed_is_error(self):
        with self.assertRaises(ValueError):
            parse_range("2026-10-31..2026-10-01")

    def test_malformed_dates_are_errors(self):
        for text in [
            "2026-02-30..2026-03-01",
            "2026-10-01..2026-10-32",
            "2026-10-00..2026-10-31",
            "2026-1-1..2026-10-31",
            "26-10-01..2026-10-31",
            "2026-10-01..2026-13-01",
            "2026-10-01..",
            "..2026-10-01",
        ]:
            with self.subTest(text=text):
                self.assertNotIn(text, ["2026-10-01..", "..2026-10-01"])  # open ends are covered elsewhere
                with self.assertRaises(ValueError):
                    parse_range(text)


